    private static void init() {
        ArrayList<String> keyList = new ArrayList();
        for (int i = commandString.length - 1; i >= 0; i--) {
            Command com = new Command(commandString[i]);
            codeCommands.put(com.val, com);
            ArrayList<Command> cList = mnemonicList.get(com.mnem);
            if (null!=cList){
                cList.add(com);
            }else{
                Command cc = mnemonicCommands.get(com.mnem);
                if (null==cc){
                    mnemonicCommands.put(com.mnem, com);
                    keyList.add(com.mnem);
                }else { // repeated command (several neg, im 1, retn et.c.)
                    ArrayList<Command> newList = new ArrayList<>();
                    newList.add(cc);
                    newList.add(com);
                    mnemonicCommands.remove(cc.mnem);
                    mnemonicList.put(com.mnem, newList);
                }
            }
        }
        mnemonic = keyList.toArray(new String[keyList.size()]);
        Arrays.sort(mnemonic);
        // add shifts
        ArrayList<Command> shifts = new ArrayList<>();
        shifts.add(codeCommands.get(0xcb27));
        shifts.add(codeCommands.get(0xcb2f));
        shifts.add(codeCommands.get(0xcb37));
        shifts.add(codeCommands.get(0xcb3f));
        named_sets_command.put("sh", shifts);
        named_sets_command.put("shi", shifts);
    }
